// 修复前（N+1）：对每个 author 各查一次 posts
function listNaive(db) {
  const authors = db.findAllAuthors();               // 1 次
  return authors.map(a => ({
    name: a.name,
    posts: db.findPostsByAuthorId(a.id).map(p => p.title),   // N 次
  }));
}

// 修复后：一次批量取全部关联，再在内存里按外键分组
function listBatched(db) {
  const authors = db.findAllAuthors();                       // 1 次
  const ids = authors.map(a => a.id);
  const allPosts = db.findPostsByAuthorIds(ids);             // 1 次（IN 查询）
  const byAuthor = new Map();
  for (const p of allPosts) {
    if (!byAuthor.has(p.authorId)) byAuthor.set(p.authorId, []);
    byAuthor.get(p.authorId).push(p.title);
  }
  return authors.map(a => ({ name: a.name, posts: byAuthor.get(a.id) || [] }));
}

// 可运行的最小数据库桩：对操作计数
function makeDb() {
  const authors = [1, 2, 3, 4, 5].map(i => ({ id: i, name: 'author' + i }));
  const posts = [];
  let pid = 0;
  for (const a of authors) {
    for (let i = 0; i < (a.id % 3) + 1; i++) {
      pid += 1;
      posts.push({ id: pid, authorId: a.id, title: 'post' + pid });
    }
  }
  let ops = 0;
  return {
    get ops() { return ops; },
    reset() { ops = 0; },
    findAllAuthors() { ops += 1; return authors.slice(); },
    findPostsByAuthorId(id) { ops += 1; return posts.filter(p => p.authorId === id); },
    findPostsByAuthorIds(ids) { ops += 1; return posts.filter(p => ids.includes(p.authorId)); },
  };
}

const db = makeDb();
db.reset();
const naive = listNaive(db);
console.log('naive_ops=' + db.ops);
db.reset();
const batched = listBatched(db);
console.log('batched_ops=' + db.ops);
console.log('same_result=' + (JSON.stringify(naive) === JSON.stringify(batched)));
console.log('batched_is_constant_ops=' + (db.ops === 2));

const SORTABLE = new Set(['id', 'createdAt', 'score', 'title']);
const FILTERABLE = { status: 'string', tag: 'string', score: 'integer' };
const MAX_LIMIT = 100;

function parseQuery(raw) {
  const sp = new URLSearchParams(raw);
  const errors = [];
  const out = { orderSql: null, filters: {}, limit: 20, offset: 0 };

  const sortRaw = sp.get('sort');
  if (sortRaw !== null) {
    const m = /^(-?)([A-Za-z][A-Za-z0-9]{0,20})$/.exec(sortRaw);
    if (!m) errors.push('sort: malformed token');
    else if (!SORTABLE.has(m[2])) errors.push('sort: field not in whitelist');
    else out.orderSql = '"' + m[2] + '" ' + (m[1] === '-' ? 'DESC' : 'ASC');
  }
  for (const [k, kind] of Object.entries(FILTERABLE)) {
    const v = sp.get(k);
    if (v === null) continue;
    if (kind === 'integer') {
      if (!/^-?\d{1,9}$/.test(v)) { errors.push('filter ' + k + ': not an integer'); continue; }
      out.filters[k] = Number(v);
    } else {
      if (!/^[A-Za-z0-9_-]{1,40}$/.test(v)) { errors.push('filter ' + k + ': illegal characters'); continue; }
      out.filters[k] = v;
    }
  }
  const limit = sp.get('limit');
  if (limit !== null) {
    if (!/^\d{1,9}$/.test(limit) || Number(limit) < 1) errors.push('limit: invalid');
    else out.limit = Math.min(Number(limit), MAX_LIMIT);
  }
  return { ok: errors.length === 0, errors, query: out };
}

const cases = [
  ['sort=-score&status=published&limit=99999', true],
  ['sort=password', false],
  ['sort=id%3B%20DROP%20TABLE%20articles', false],
  ['tag=%3Cscript%3E', false],
  ['score=abc', false],
];
for (const [raw, expectOk] of cases) {
  const r = parseQuery(raw);
  console.log(raw + ' -> ok=' + r.ok + ' match=' + (r.ok === expectOk)
    + ' orderSql=' + (r.query.orderSql === null ? 'null' : JSON.stringify(r.query.orderSql))
    + ' limit=' + r.query.limit + ' errors=' + JSON.stringify(r.errors));
}

function createBucket(capacity, refillPerSec) {
  let tokens = capacity;
  let last = 0;
  let now = 0;
  return {
    advance(ms) { now += ms; },
    tryConsume() {
      const added = (now - last) / 1000 * refillPerSec;
      if (added > 0) { tokens = Math.min(capacity, tokens + added); last = now; }
      const allowed = tokens >= 1;
      if (allowed) tokens -= 1;
      return { allowed, left: Math.round(tokens * 1000) / 1000 };
    },
  };
}

function run(capacity, rate, gaps) {
  const b = createBucket(capacity, rate);
  const out = [];
  for (let i = 0; i < gaps.length; i++) {
    if (gaps[i] > 0) b.advance(gaps[i]);
    out.push(b.tryConsume().allowed ? 'A' : 'D');
  }
  return out.join('');
}

// 容量 3、补 1/s：t=0 连打 6 个 -> 前 3 个放行
console.log('burst=' + run(3, 1, [0, 0, 0, 0, 0, 0]));
// 同配置、间隔 1s：每个间隔内补满 1 个 -> 全部放行
console.log('steady=' + run(3, 1, [0, 1000, 1000, 1000, 1000]));
// 容量 2、补 1/s、间隔 500ms：每两个间隔才攒够 1 个令牌 -> A/A 之后 D/A 交替
console.log('mixed=' + run(2, 1, [0, 0, 500, 500, 500, 500, 500]));

// 第一个 >= target 的位置（lower_bound）；不存在则返回 nums.length
function lowerBound(nums, target) {
  let lo = 0;
  let hi = nums.length;
  while (lo < hi) {
    const mid = lo + ((hi - lo) >> 1);
    if (nums[mid] < target) lo = mid + 1;
    else hi = mid;
  }
  return lo;
}

const nums = [10, 20, 20, 30, 40];
console.log('lb_20=' + lowerBound(nums, 20));   // 第一个 20 的下标
console.log('lb_25=' + lowerBound(nums, 25));   // 插入位置
console.log('lb_41=' + lowerBound(nums, 41));   // 越界 -> 返回长度
console.log('lb_5=' + lowerBound(nums, 5));

function search(nums, target) {
  let lo = 0;
  let hi = nums.length - 1;
  while (lo <= hi) {
    const mid = lo + ((hi - lo) >> 1);   // 防溢出写法
    if (nums[mid] === target) return mid;
    if (nums[mid] < target) lo = mid + 1;
    else hi = mid - 1;
  }
  return -1;
}

